function why2(ar1, ar2, en1, en2) {
  return { ar: `${ar1}\n\n${ar2}`, en: `${en1}\n\n${en2}` };
}
function c(arT, arB, enT, enB) {
  return { title: { ar: arT, en: enT }, body: { ar: arB, en: enB } };
}
function pit(arBad, arGood, enBad, enGood) {
  return { ar: [arBad, arGood], en: [enBad, enGood] };
}
function q(arQ, arA, enQ, enA) {
  return { q: { ar: arQ, en: enQ }, a: { ar: arA, en: enA } };
}
function L(spec) {
  return spec;
}

