    code: { ar: { lang: "csharp", source: `public record LessonQuery(int Page = 1, int Size = 20, string? Search = null);\n\napp.MapGet("/search", ( [AsParameters] LessonQuery q, ILessonService svc) =>\n  svc.SearchAsync(q));\n\napp.MapPost("/", async (CreateLessonDto dto, ILessonService svc, CancellationToken ct) => {\n  var created = await svc.CreateAsync(dto, ct);\n  return Results.Created($"/api/lessons/{created.Id}", created);\n});`, explain: "AsParameters للquery + FromBody implicit على POST DTO." }, en: { lang: "csharp", source: `public record LessonQuery(int Page = 1, int Size = 20, string? Search = null);\n\napp.MapGet("/search", ( [AsParameters] LessonQuery q, ILessonService svc) =>\n  svc.SearchAsync(q));\n\napp.MapPost("/", async (CreateLessonDto dto, ILessonService svc, CancellationToken ct) => {\n  var created = await svc.CreateAsync(dto, ct);\n  return Results.Created($"/api/lessons/{created.Id}", created);\n});`, explain: "AsParameters for query + implicit FromBody on POST DTO." } },
