    why: why2(
      "Never trust client input — validate DTOs before DB. **DataAnnotations** `[Required]`, `[MaxLength]`, `[EmailAddress]`. **FluentValidation** rules أغنى وtestable. Minimal APIs: `.AddEndpointFilter<ValidationFilter>()` أو `[Validate]` (.NET 8+).",
      "Return `Results.ValidationProblem(errors)` → 400 + RFC 7807 ProblemDetails. Server-side validation complements client — لا replace. EF Core لا يvalidate business rules — application layer does.",
      "Never trust client input — validate DTOs before DB. **DataAnnotations** `[Required]`, `[MaxLength]`, `[EmailAddress]`. **FluentValidation** richer, testable rules. Minimal APIs: `.AddEndpointFilter<ValidationFilter>()` or `[Validate]` (.NET 8+).",
      "Return `Results.ValidationProblem(errors)` → 400 + RFC 7807 ProblemDetails. Server-side validation complements client — does not replace. EF Core does not validate business rules — application layer does.",
    ),
    goals: { ar: ["DataAnnotations على DTOs", "FluentValidation validator class", "ValidationProblem response", "ValidateOnStart للoptions"], en: ["DataAnnotations on DTOs", "FluentValidation validator class", "ValidationProblem response", "ValidateOnStart for options"] },
    concepts: [
      c("DataAnnotations", "`[Required]`, `[StringLength(100)]`, `[Range(1,500)]` — IValidatableObject for cross-field.", "DataAnnotations", "`[Required]`, `[StringLength(100)]`, `[Range(1,500)]` — IValidatableObject for cross-field."),
      c("FluentValidation", "`AbstractValidator<CreateLessonDto>` — `RuleFor(x => x.Title).NotEmpty().MaximumLength(200)`. Register `AddValidatorsFromAssembly`.", "FluentValidation", "`AbstractValidator<CreateLessonDto>` — `RuleFor(x => x.Title).NotEmpty().MaximumLength(200)`. Register `AddValidatorsFromAssembly`."),
      c("ProblemDetails", "ValidationProblem dictionary field → errors — consistent API errors.", "ProblemDetails", "ValidationProblem dictionary field → errors — consistent API errors."),
      c("Business validation", "Service layer: duplicate slug → 409 Conflict — not annotation.", "Business validation", "Service layer: duplicate slug → 409 Conflict — not annotation."),
    ],
    steps: { ar: ["Annotations على CreateLessonDto", "Install FluentValidation.AspNetCore", "Write CreateLessonValidator", "Endpoint returns ValidationProblem", "Unit test validator", "409 for duplicate slug in service"], en: ["Annotations on CreateLessonDto", "Install FluentValidation.AspNetCore", "Write CreateLessonValidator", "Endpoint returns ValidationProblem", "Unit test validator", "409 for duplicate slug in service"] },
    code: { ar: { lang: "csharp", source: `public class CreateLessonDto {\n  [Required, StringLength(200)] public string Title { get; set; } = "";\n  [Range(5, 120)] public int Duration { get; set; }\n}\n\npublic class CreateLessonValidator : AbstractValidator<CreateLessonDto> {\n  public CreateLessonValidator() {\n    RuleFor(x => x.Title).NotEmpty().MaximumLength(200);\n    RuleFor(x => x.Duration).InclusiveBetween(5, 120);\n  }\n}`, explain: "FluentValidation rules — testable independently from endpoints." }, en: { lang: "csharp", source: `public class CreateLessonDto {\n  [Required, StringLength(200)] public string Title { get; set; } = "";\n  [Range(5, 120)] public int Duration { get; set; }\n}\n\npublic class CreateLessonValidator : AbstractValidator<CreateLessonDto> {\n  public CreateLessonValidator() {\n    RuleFor(x => x.Title).NotEmpty().MaximumLength(200);\n    RuleFor(x => x.Duration).InclusiveBetween(5, 120);\n  }\n}`, explain: "FluentValidation rules — testable independently from endpoints." } },
    pitfalls: [pit("validation فقط client-side", "always server-side", "client-only validation", "always server-side"), pit("500 on validation fail", "return 400 ValidationProblem", "500 on validation fail", "return 400 ValidationProblem"), pit("annotations على entities", "validate DTOs not EF entities", "annotations on entities", "validate DTOs not EF entities"), pit("duplicate rules scattered", "centralize validators", "duplicate rules scattered", "centralize validators")],
    discussion: [q("FluentValidation vs Annotations?", "FV for complex — annotations for simple.", "FluentValidation vs Annotations?", "FV for complex — annotations for simple."), q("Minimal API validate?", "Filter or manual validator inject.", "Minimal API validate?", "Filter or manual validator inject."), q("Localization errors?", "IStringLocalizer in FV.", "Localization errors?", "IStringLocalizer in FV."), q("Validate never attribute?", "Skip binding validation rare cases.", "Validate never attribute?", "Skip binding validation rare cases.")],
