    code: { ar: { lang: "csharp", source: `[ApiController]\n[Route("api/[controller]")]\npublic class LessonsController(ILessonService svc) : ControllerBase {\n  [HttpGet("{id:int}")]\n  public async Task<ActionResult<LessonDto>> Get(int id, CancellationToken ct) {\n    var item = await svc.GetAsync(id, ct);\n    return item is null ? NotFound() : Ok(item);\n  }\n  [HttpPost]\n  public async Task<ActionResult<LessonDto>> Create(CreateLessonDto dto, CancellationToken ct) {\n    var created = await svc.CreateAsync(dto, ct);\n    return CreatedAtAction(nameof(Get), new { id = created.Id }, created);\n  }\n}`, explain: "Primary constructor DI + ActionResult<T> — نمط MVC API حديث." }, en: { lang: "csharp", source: `[ApiController]\n[Route("api/[controller]")]\npublic class LessonsController(ILessonService svc) : ControllerBase {\n  [HttpGet("{id:int}")]\n  public async Task<ActionResult<LessonDto>> Get(int id, CancellationToken ct) {\n    var item = await svc.GetAsync(id, ct);\n    return item is null ? NotFound() : Ok(item);\n  }\n  [HttpPost]\n  public async Task<ActionResult<LessonDto>> Create(CreateLessonDto dto, CancellationToken ct) {\n    var created = await svc.CreateAsync(dto, ct);\n    return CreatedAtAction(nameof(Get), new { id = created.Id }, created);\n  }\n}`, explain: "Primary constructor DI + ActionResult<T> — modern MVC API pattern." } },
