    code: { ar: { lang: "csharp", source: `public class StudyDbContext(DbContextOptions<StudyDbContext> options) : DbContext(options) {\n  public DbSet<Lesson> Lessons => Set<Lesson>();\n  protected override void OnModelCreating(ModelBuilder modelBuilder) {\n    modelBuilder.Entity<Lesson>(e => {\n      e.Property(x => x.Title).HasMaxLength(200).IsRequired();\n    });\n  }\n}\nbuilder.Services.AddDbContext<StudyDbContext>(o =>\n  o.UseSqlite(builder.Configuration.GetConnectionString("Default")));`, explain: "DbContext + Fluent config + SQLite — جاهز للmigrations." }, en: { lang: "csharp", source: `public class StudyDbContext(DbContextOptions<StudyDbContext> options) : DbContext(options) {\n  public DbSet<Lesson> Lessons => Set<Lesson>();\n  protected override void OnModelCreating(ModelBuilder modelBuilder) {\n    modelBuilder.Entity<Lesson>(e => {\n      e.Property(x => x.Title).HasMaxLength(200).IsRequired();\n    });\n  }\n}\nbuilder.Services.AddDbContext<StudyDbContext>(o =>\n  o.UseSqlite(builder.Configuration.GetConnectionString("Default")));`, explain: "DbContext + Fluent config + SQLite — ready for migrations." } },
