    code: { ar: { lang: "csharp", source: `public class Track {\n  public int Id { get; set; }\n  public string Name { get; set; } = "";\n  public List<Lesson> Lessons { get; set; } = [];\n}\npublic class Lesson {\n  public int Id { get; set; }\n  public int TrackId { get; set; }\n  public Track Track { get; set; } = null!;\n}\n// query\nawait context.Lessons.Include(l => l.Track).AsNoTracking().ToListAsync(ct);`, explain: "Include Track مع AsNoTracking — مناسب لقراءة API." }, en: { lang: "csharp", source: `public class Track {\n  public int Id { get; set; }\n  public string Name { get; set; } = "";\n  public List<Lesson> Lessons { get; set; } = [];\n}\npublic class Lesson {\n  public int Id { get; set; }\n  public int TrackId { get; set; }\n  public Track Track { get; set; } = null!;\n}\n// query\nawait context.Lessons.Include(l => l.Track).AsNoTracking().ToListAsync(ct);`, explain: "Include Track with AsNoTracking — good for API reads." } },
