    code: { ar: { lang: "csharp", source: `public async Task<PagedResult<LessonDto>> SearchAsync(LessonQuery q, CancellationToken ct) {\n  var query = context.Lessons.AsNoTracking();\n  if (!string.IsNullOrWhiteSpace(q.Search))\n    query = query.Where(l => l.Title.Contains(q.Search));\n  var total = await query.CountAsync(ct);\n  var items = await query.OrderBy(l => l.Title)\n    .Skip((q.Page - 1) * q.Size).Take(q.Size)\n    .Select(l => new LessonDto(l.Id, l.Title, l.Duration)).ToListAsync(ct);\n  return new PagedResult<LessonDto> { Items = items, Total = total };\n}`, explain: "Filter + count + page + projection — pattern قائمة API كامل." }, en: { lang: "csharp", source: `public async Task<PagedResult<LessonDto>> SearchAsync(LessonQuery q, CancellationToken ct) {\n  var query = context.Lessons.AsNoTracking();\n  if (!string.IsNullOrWhiteSpace(q.Search))\n    query = query.Where(l => l.Title.Contains(q.Search));\n  var total = await query.CountAsync(ct);\n  var items = await query.OrderBy(l => l.Title)\n    .Skip((q.Page - 1) * q.Size).Take(q.Size)\n    .Select(l => new LessonDto(l.Id, l.Title, l.Duration)).ToListAsync(ct);\n  return new PagedResult<LessonDto> { Items = items, Total = total };\n}`, explain: "Filter + count + page + projection — full API list pattern." } },
