    code: { ar: { lang: "csharp", source: `builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)\n  .AddJwtBearer(o => {\n    o.TokenValidationParameters = new TokenValidationParameters {\n      ValidateIssuer = true, ValidIssuer = jwt.Issuer,\n      ValidateAudience = true, ValidAudience = jwt.Audience,\n      ValidateIssuerSigningKey = true,\n      IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.Key))\n    };\n  });\napp.UseAuthentication();\napp.UseAuthorization();\napp.MapGet("/me", [Authorize] (ClaimsPrincipal user) => user.Identity?.Name);`, explain: "JwtBearer validation + Authorize endpoint — pipeline order critical." }, en: { lang: "csharp", source: `builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)\n  .AddJwtBearer(o => {\n    o.TokenValidationParameters = new TokenValidationParameters {\n      ValidateIssuer = true, ValidIssuer = jwt.Issuer,\n      ValidateAudience = true, ValidAudience = jwt.Audience,\n      ValidateIssuerSigningKey = true,\n      IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.Key))\n    };\n  });\napp.UseAuthentication();\napp.UseAuthorization();\napp.MapGet("/me", [Authorize] (ClaimsPrincipal user) => user.Identity?.Name);`, explain: "JwtBearer validation + Authorize endpoint — pipeline order critical." } },
